import{_ as a,o as t,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph SMB  Opening Windows to the Ceph World","description":"","frontmatter":{"title":"Ceph SMB  Opening Windows to the Ceph World","date":"2025-06-24T00:00:00.000Z","updated":"2025-06-24T00:00:00.000Z","tags":["CephFS","Samba","SMB 协议","Ceph 分布式存储","Ceph 集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_SMB_Opening_Windows_to_the_Ceph_World.md","filePath":"posts/2025/Ceph_SMB_Opening_Windows_to_the_Ceph_World.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Ceph_SMB_Opening_Windows_to_the_Ceph_World.md"};function i(n,e,s,h,d,_){return t(),o("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要-ceph-smb-集成与管理模块开发讨论" tabindex="-1">会议纪要：Ceph SMB 集成与管理模块开发讨论 <a class="header-anchor" href="#会议纪要-ceph-smb-集成与管理模块开发讨论" aria-label="Permalink to &quot;会议纪要：Ceph SMB 集成与管理模块开发讨论&quot;">​</a></h3><h4 id="_1-会议基本信息" tabindex="-1">1. 会议基本信息 <a class="header-anchor" href="#_1-会议基本信息" aria-label="Permalink to &quot;1. 会议基本信息&quot;">​</a></h4><ul><li><strong>主讲人</strong>：Sachin Prabu（IBM 软件开发者，原 Red Hat SMB/Samba 团队成员）</li><li><strong>主题</strong>：通过 SMB 协议集成 CephFS（Opening Windows to the Ceph World）</li><li><strong>背景</strong>： <ul><li>CephFS 通过 Samba 提供 SMB（Server Message Block）协议支持，实现跨平台文件共享。</li><li>目标是简化 CephFS 通过 SMB 导出的流程，并解决旧版 VFS 模块的维护问题。</li></ul></li></ul><h4 id="_2-关键讨论内容" tabindex="-1">2. 关键讨论内容 <a class="header-anchor" href="#_2-关键讨论内容" aria-label="Permalink to &quot;2. 关键讨论内容&quot;">​</a></h4><h5 id="_2-1-现有架构与改进" tabindex="-1">2.1 现有架构与改进 <a class="header-anchor" href="#_2-1-现有架构与改进" aria-label="Permalink to &quot;2.1 现有架构与改进&quot;">​</a></h5><ul><li><strong>旧版问题</strong>：手动配置复杂，文档分散，部分 VFS 模块已无人维护。</li><li><strong>新版改进</strong>： <ul><li>引入 <code>vfs_cephfs</code> 模块，基于 <code>libcephfs</code> 底层驱动，替代旧模块。</li><li>新增 SMB Manager Module，通过声明式（YAML/JSON）或命令式（CLI）管理集群和共享。</li></ul></li></ul><h5 id="_2-2-核心组件" tabindex="-1">2.2 核心组件 <a class="header-anchor" href="#_2-2-核心组件" aria-label="Permalink to &quot;2.2 核心组件&quot;">​</a></h5><ul><li><strong>Orchestration 流程</strong>：包括 Init Containers 和 Sidecar Containers（如 SMBD、CTDB、Winbind、Prometheus）。</li><li><strong>Proxy 服务</strong>：解决 Samba 多进程连接导致的内存问题，通过代理集中管理 <code>libcephfs</code> 连接。</li></ul><h5 id="_2-3-功能演示-demo" tabindex="-1">2.3 功能演示（Demo） <a class="header-anchor" href="#_2-3-功能演示-demo" aria-label="Permalink to &quot;2.3 功能演示（Demo）&quot;">​</a></h5><ul><li><strong>场景</strong>：创建两个集群：用户认证集群和 Active Directory 集群。</li><li><strong>操作命令示例</strong>：<code>ceph smb cluster create starter --user-auth --placement=label:first</code> 和 <code>ceph smb share create starter share1 --fs-volume=cephfs/demos/subvol1</code>。</li></ul><h5 id="_2-4-新功能与未来计划" tabindex="-1">2.4 新功能与未来计划 <a class="header-anchor" href="#_2-4-新功能与未来计划" aria-label="Permalink to &quot;2.4 新功能与未来计划&quot;">​</a></h5><ul><li><strong>已实现功能</strong>：Case Insensitivity、快照支持、多通道传输。</li><li><strong>未来计划</strong>：QoS 限制、离线域加入、多协议支持（早期阶段）。</li></ul><h4 id="_3-决策与行动计划" tabindex="-1">3. 决策与行动计划 <a class="header-anchor" href="#_3-决策与行动计划" aria-label="Permalink to &quot;3. 决策与行动计划&quot;">​</a></h4><ul><li><strong>短期行动</strong>：完善 IO 统计并集成到 Dashboard，开发 gRPC 接口提升管理模块扩展性。</li><li><strong>长期规划</strong>：探索 Multi-protocol Support 的可行性。</li></ul><h4 id="_4-问答环节" tabindex="-1">4. 问答环节 <a class="header-anchor" href="#_4-问答环节" aria-label="Permalink to &quot;4. 问答环节&quot;">​</a></h4><ul><li><strong>安全问题</strong>：已修复 CLI 中密码明文显示的问题。</li><li><strong>测试工具</strong>：使用 <code>smbclient</code> 进行基础验证，但生产环境需结合 AD 或加密认证。</li></ul><h4 id="_5-参会人员反馈" tabindex="-1">5. 参会人员反馈 <a class="header-anchor" href="#_5-参会人员反馈" aria-label="Permalink to &quot;5. 参会人员反馈&quot;">​</a></h4><ul><li>演示获得积极反响，团队将持续优化 SMB 与 CephFS 的集成体验。</li></ul><h4 id="_6-后续跟进" tabindex="-1">6. 后续跟进 <a class="header-anchor" href="#_6-后续跟进" aria-label="Permalink to &quot;6. 后续跟进&quot;">​</a></h4><ul><li>Sachin Prabu 将通过邮件提供进一步支持。</li></ul>',20)])])}const p=a(r,[["render",i]]);export{u as __pageData,p as default};
